create extension if not exists pgcrypto;
create table public.profiles(id uuid primary key references auth.users(id) on delete cascade, full_name text, whatsapp text, role text not null default 'customer' check(role in ('customer','super_admin','order_admin','finance_admin','product_admin')), created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.categories(id uuid primary key default gen_random_uuid(), name text not null unique, slug text not null unique, description text, icon text, sort_order int not null default 0, is_active boolean not null default true, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.products(id uuid primary key default gen_random_uuid(), category_id uuid references public.categories(id) on delete set null, name text not null, slug text not null unique, short_description text, description text, logo_url text, status text not null default 'draft' check(status in ('draft','published','out_of_stock','hidden','archived')), stock_mode text not null default 'manual' check(stock_mode in ('manual','managed')), stock_quantity int check(stock_quantity is null or stock_quantity >= 0), is_featured boolean not null default false, is_best_seller boolean not null default false, is_new boolean not null default false, sort_order int not null default 0, terms text, activation_method text, warranty_terms text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.product_packages(id uuid primary key default gen_random_uuid(), product_id uuid not null references public.products(id) on delete restrict, name text not null, duration_days int not null check(duration_days > 0), price_idr bigint not null check(price_idr >= 0), compare_at_price_idr bigint check(compare_at_price_idr is null or compare_at_price_idr >= price_idr), stock_quantity int check(stock_quantity is null or stock_quantity >= 0), activation_method text, terms text, warranty_terms text, is_recommended boolean not null default false, is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create table public.vouchers(id uuid primary key default gen_random_uuid(), code text not null unique, discount_type text not null check(discount_type in ('percentage','fixed')), discount_value numeric(12,2) not null check(discount_value > 0), max_discount_idr bigint, minimum_purchase_idr bigint not null default 0, usage_limit int, per_customer_limit int, usage_count int not null default 0, starts_at timestamptz, ends_at timestamptz, eligible_category_ids uuid[] not null default '{}', eligible_product_ids uuid[] not null default '{}', is_active boolean not null default true, created_at timestamptz not null default now());
create table public.banners(id uuid primary key default gen_random_uuid(), title text not null, subtitle text, image_url text, target_url text, placement text not null default 'catalog', starts_at timestamptz, ends_at timestamptz, is_active boolean not null default true, sort_order int not null default 0, created_at timestamptz not null default now());
create table public.orders(id uuid primary key default gen_random_uuid(), order_number text not null unique, customer_id uuid references auth.users(id) on delete set null, customer_name text not null, customer_whatsapp text not null, customer_email text not null, is_guest boolean not null default true, subtotal_idr bigint not null check(subtotal_idr >= 0), discount_idr bigint not null default 0 check(discount_idr >= 0), fee_idr bigint not null default 0 check(fee_idr >= 0), total_idr bigint not null check(total_idr >= 0), voucher_code text, payment_method text not null check(payment_method in ('qris','ewallet','wallet')), payment_status text not null default 'awaiting_payment' check(payment_status in ('awaiting_payment','submitted','under_review','paid','rejected','expired','refunded')), fulfillment_status text not null default 'not_started' check(fulfillment_status in ('not_started','processing','waiting_for_info','completed','cancelled')), expires_at timestamptz, notes text, created_at timestamptz not null default now(), updated_at timestamptz not null default now());
create index orders_customer_id_idx on public.orders(customer_id); create index orders_created_at_idx on public.orders(created_at desc); create index orders_payment_status_idx on public.orders(payment_status); create index orders_fulfillment_status_idx on public.orders(fulfillment_status);
create table public.order_items(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, product_id uuid references public.products(id) on delete set null, package_id uuid references public.product_packages(id) on delete set null, product_name_snapshot text not null, package_name_snapshot text not null, duration_days_snapshot int not null, unit_price_idr_snapshot bigint not null, quantity int not null default 1 check(quantity > 0), terms_snapshot text, created_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, method text not null check(method in ('qris','ewallet')), provider text, amount_idr bigint not null check(amount_idr > 0), proof_storage_path text, provider_reference text, status text not null default 'submitted' check(status in ('submitted','under_review','approved','rejected')), reviewed_by uuid references auth.users(id), reviewed_at timestamptz, rejection_reason text, created_at timestamptz not null default now());
create table public.wallets(user_id uuid primary key references auth.users(id) on delete cascade, balance_idr bigint not null default 0 check(balance_idr >= 0), updated_at timestamptz not null default now());
create table public.wallet_transactions(id uuid primary key default gen_random_uuid(), user_id uuid not null references auth.users(id) on delete cascade, transaction_type text not null check(transaction_type in ('deposit','purchase','refund','adjustment')), direction text not null check(direction in ('credit','debit')), amount_idr bigint not null check(amount_idr > 0), balance_before_idr bigint not null, balance_after_idr bigint not null, reference_type text, reference_id uuid, description text, created_by uuid references auth.users(id), created_at timestamptz not null default now());
create index wallet_transactions_user_created_idx on public.wallet_transactions(user_id,created_at desc);
create table public.active_products(id uuid primary key default gen_random_uuid(), order_item_id uuid not null unique references public.order_items(id) on delete restrict, customer_id uuid references auth.users(id) on delete set null, customer_name text not null, customer_whatsapp text not null, product_name_snapshot text not null, package_name_snapshot text not null, activation_date date not null, expiry_date date not null, status text not null default 'active' check(status in ('active','expired','suspended','cancelled')), activation_notes text, created_by uuid references auth.users(id), created_at timestamptz not null default now(), updated_at timestamptz not null default now(), check(expiry_date >= activation_date));
create index active_products_customer_idx on public.active_products(customer_id,expiry_date);
create table public.order_status_history(id uuid primary key default gen_random_uuid(), order_id uuid not null references public.orders(id) on delete cascade, payment_status text, fulfillment_status text, note text, changed_by uuid references auth.users(id), created_at timestamptz not null default now());
create table public.audit_logs(id uuid primary key default gen_random_uuid(), actor_id uuid references auth.users(id), action text not null, entity_type text not null, entity_id uuid, metadata jsonb not null default '{}', created_at timestamptz not null default now());
create or replace function public.set_updated_at() returns trigger language plpgsql set search_path = '' as $$ begin new.updated_at = now(); return new; end; $$;
do $$ declare t text; begin foreach t in array array['profiles','categories','products','product_packages','orders','wallets','active_products'] loop execute format('create trigger %I before update on public.%I for each row execute function public.set_updated_at()',t||'_set_updated_at',t); end loop; end $$;
alter table public.profiles enable row level security; alter table public.categories enable row level security; alter table public.products enable row level security; alter table public.product_packages enable row level security; alter table public.vouchers enable row level security; alter table public.banners enable row level security; alter table public.orders enable row level security; alter table public.order_items enable row level security; alter table public.payments enable row level security; alter table public.wallets enable row level security; alter table public.wallet_transactions enable row level security; alter table public.active_products enable row level security; alter table public.order_status_history enable row level security; alter table public.audit_logs enable row level security;
grant select on public.categories,public.products,public.product_packages,public.banners to anon,authenticated;
grant select on public.profiles,public.orders,public.order_items,public.wallets,public.wallet_transactions,public.active_products,public.order_status_history to authenticated;
create policy "Public reads active categories" on public.categories for select to anon,authenticated using(is_active=true);
create policy "Public reads published products" on public.products for select to anon,authenticated using(status='published');
create policy "Public reads active packages for published products" on public.product_packages for select to anon,authenticated using(is_active=true and exists(select 1 from public.products p where p.id=product_id and p.status='published'));
create policy "Public reads active banners" on public.banners for select to anon,authenticated using(is_active=true and (starts_at is null or starts_at<=now()) and (ends_at is null or ends_at>=now()));
create policy "Users read own profile" on public.profiles for select to authenticated using((select auth.uid())=id);
create policy "Users read own orders" on public.orders for select to authenticated using((select auth.uid())=customer_id);
create policy "Users read own order items" on public.order_items for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=(select auth.uid())));
create policy "Users read own wallet" on public.wallets for select to authenticated using((select auth.uid())=user_id);
create policy "Users read own wallet transactions" on public.wallet_transactions for select to authenticated using((select auth.uid())=user_id);
create policy "Users read own active products" on public.active_products for select to authenticated using((select auth.uid())=customer_id);
create policy "Users read own order status history" on public.order_status_history for select to authenticated using(exists(select 1 from public.orders o where o.id=order_id and o.customer_id=(select auth.uid())));
create policy "Staff read profiles" on public.profiles for select to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','order_admin','finance_admin','product_admin'));
create policy "Staff manage categories" on public.categories for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin'));
create policy "Staff manage products" on public.products for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin'));
create policy "Staff manage packages" on public.product_packages for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin'));
create policy "Staff manage vouchers" on public.vouchers for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin'));
create policy "Staff manage banners" on public.banners for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','product_admin'));
create policy "Staff manage orders" on public.orders for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','order_admin','finance_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','order_admin','finance_admin'));
create policy "Staff manage payments" on public.payments for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','finance_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','finance_admin'));
create policy "Staff manage wallets" on public.wallets for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','finance_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','finance_admin'));
create policy "Staff manage wallet transactions" on public.wallet_transactions for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','finance_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','finance_admin'));
create policy "Staff manage active products" on public.active_products for all to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin','order_admin')) with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','order_admin'));
create policy "Staff read audit logs" on public.audit_logs for select to authenticated using((auth.jwt()->'app_metadata'->>'role') in ('super_admin'));
create policy "Staff insert audit logs" on public.audit_logs for insert to authenticated with check((auth.jwt()->'app_metadata'->>'role') in ('super_admin','order_admin','finance_admin','product_admin'));
revoke all on public.payments,public.vouchers,public.audit_logs from anon,authenticated;
grant select,insert,update,delete on public.vouchers to authenticated;
grant select,insert,update,delete on public.payments to authenticated;
grant select,insert on public.audit_logs to authenticated;
